for l,entry in zip(course['lessons'],lessons):
    title,theory,example,drill,quiz,rubric=entry
    l['title']=title
    l['theory']=theory.split('\n')
    l['example']={'before':example.split('|')[0],'after':example.split('|')[1],'label':'Exemplo didático de formulação; não representa um resultado de pesquisa.'}
    l['practiceSteps']=drill.split('|')
    q=quiz.split('|');l['check']={'question':q[0],'options':q[1:4],'correct':int(q[4]),'feedback':q[5]}
    l['rubric']=rubric.split('|')
    l['module']=('Fundamentos','Voz, presença e recursos','Narrativa e públicos','Prática e autonomia')[(int(l['id'][1:])-1)//5]
    l['schedule']=[{'label':'Leitura e compreensão','minutes':10},{'label':'Análise do exemplo','minutes':10},{'label':'Prática e produção','minutes':25},{'label':'Revisão e feedback','minutes':10},{'label':'Reflexão e registro','minutes':5}]
    l['links']=[{'label':'Toastmasters — preparação de uma fala (em inglês)','url':'https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech','note':'Leitura complementar; o conteúdo da aula está disponível nesta plataforma.'},{'label':'COMPASS — comunicação científica e público (em inglês)','url':'https://www.compassscicomm.org/leadership-development/the-message-box/','note':'Referência externa complementar. Materiais e direitos pertencem à organização.'}]
course['version']=2
course['totalHours']=20
course['description']='20 aulas com carga de prática sugerida de 1h cada. O tempo de leitura isolado é menor que a carga total; materiais externos são opcionais.'
Path('assets/course.json').write_text(json.dumps(course,ensure_ascii=False,indent=2))
Path('assets/course-data.js').write_text('window.COURSE = '+json.dumps(course,ensure_ascii=False)+';\n')
